-- BuildPulse Social core. Private messages store ciphertext only; cryptographic protocol implementation is a separate release gate.
create table if not exists public.buildpulse_social_profiles(user_id uuid primary key references auth.users(id) on delete cascade,handle text not null unique check(handle ~ '^[A-Za-z0-9_]{3,30}$'),display_name text,bio text,avatar_path text,discoverable boolean not null default true,allow_messages text not null default 'followers' check(allow_messages in ('nobody','followers','everyone')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_social_follows(follower_id uuid not null references auth.users(id) on delete cascade,following_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table if not exists public.buildpulse_social_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,kind text not null default 'post' check(kind in ('post','blog')),title text,body text not null,media_paths text[] not null default '{}',visibility text not null default 'public' check(visibility in ('public','followers','private')),status text not null default 'published' check(status in ('draft','published','hidden','removed')),comments_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz);
create table if not exists public.buildpulse_social_conversations(id uuid primary key default gen_random_uuid(),kind text not null default 'direct' check(kind in ('direct','group','channel')),title text,encryption_mode text not null default 'e2ee' check(encryption_mode='e2ee'),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_social_members(conversation_id uuid not null references public.buildpulse_social_conversations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('member','moderator','owner')),joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table if not exists public.buildpulse_social_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.buildpulse_social_conversations(id) on delete cascade,sender_id uuid references auth.users(id) on delete set null,ciphertext text not null,nonce text not null,key_version integer not null default 1,client_message_id text not null,created_at timestamptz not null default now(),expires_at timestamptz,unique(conversation_id,client_message_id));
